package LinearActuatorModel {
    private import ISQ::*;
    private import SI::*;
    private import ScalarValues::*;

    port def SignalOut {
        out controlSignal;
    }

    port def SignalIn {
        in controlSignal;
    }

    port def TorqueOut {
        out outputTorque :> ISQ::torque;
    }

    port def TorqueIn {
        in outputTorque :> ISQ::torque;
    }

    port def SpinShaftDrive {
        out transferTorque :> ISQ::angularVelocity;
    }

    port def ShaftExtension {
        in transferTorque :> ISQ::length;
    }

    interface def Connections {
        doc /* The definition of the interface for connecting the Controls, Motor, Gear, and Shaft parts. */
        end controlSignalOut: SignalOut;
        end controlSignalIn: SignalIn;
        end torqueOut: TorqueOut;
        end torqueIn: TorqueIn;
        end spinShaftDrive: SpinShaftDrive;
        end shaftExtension: ShaftExtension;

        flow controlSignalOut.controlSignal to controlSignalIn.controlSignal;
        flow torqueOut.outputTorque to torqueIn.outputTorque;
        flow spinShaftDrive.transferTorque to shaftExtension.transferTorque;
    }

    part def Controls {
            attribute mass :> ISQ::mass;
            port signalOut : SignalOut;
            perform action turnOn;
            perform action limitSwitchActivated;
            perform action sendSignal;
            state controlState {
                state off;
                state on {
                    entry turnOn;
                    do sendSignal;
                    exit limitSwitchActivated;
                }
            }
    }

    part def Motor {
            attribute mass :> ISQ::mass;
            attribute electricalPower :> ISQ::power;
            port signalIn : SignalIn;
            port torqueOut : TorqueOut;
            perform action generateTorque;
    }

    part def Gear {
            attribute mass :> ISQ::mass;
            attribute torque :> ISQ::torque;
            port torqueIn : TorqueIn;
            port spinShaftDrive : SpinShaftDrive;
            perform action transferTorque;
    }

    part def Shaft {
            attribute mass :> ISQ::mass;
            port extendShaft : ShaftExtension;
            perform action extendingShaft;
    }

    part def Housing {
        attribute mass :> ISQ::mass;
    }

    part LinearActuator {
        part actuator_base_1 : Housing;
        part shaft_guide_2 : Shaft ;
        part shaft_with_mounting_hole_3 : Shaft;
        part mounting_hole_guard_4 : Housing;
        part shaft_drive_oring_5 : Housing;
        part shaft_stopper_6 : Housing ;
        part shaft_stopper_washer_7 : Housing;
        part shaft_stopper_screw_8 : Housing;
        part shaft_top_cap_9 : Housing;
        part shaft_enclosure_10 : Housing ;
        part shaft_enclosure_cap_11 : Housing;
        part shaft_enclosure_cap_screw_12 : Housing;
        part gear_wheel_locking_pin_13 : Gear;
        part shaft_drive_bottom_ball_bearing_14 : Gear ;
        part shaft_drive_gear_wheel_15 : Gear;
        part shaft_drive_ball_bearing_16 : Gear;
        part shaft_drive_bumper_17 : Gear;
        part shaft_drive_18 : Gear ;
        part rotor_bottom_support_screw_19 : Housing;
        part bottom_cap_with_mounting_hole_20 : Housing;
        part bottom_cap_mounting_plate_21 : Housing;
        part mounting_plate_screw_22 : Housing ;
        part limit_switch_23 : Controls;
        part limit_switch_carrier_24 : Controls;
        part diode_25 : Controls;
        part wire_26 : Controls ;
        part shaft_enclosure_central_screw_27 : Housing;
        part shaft_enclosure_side_screw_28 : Housing;
        part power_cable_with_mounting_29 : Controls;
        part power_cable_screw_30 : Housing ;
        part motor_case_gasket_31 : Housing;
        part brush_holder_pcb_32 : Controls;
        part brush_holder_pcb_screws_33 : Housing;
        part brush_spring_34 : Housing ;
        part electric_motor_brush_35 : Controls;
        part brush_wire_screw_36 : Housing;
        part rotor_bottom_bearing_37 : Housing;
        part locking_washer_38 : Housing ;
        part electric_motor_rotor_39 : Motor;
        part rotor_top_bearing_40 : Housing;
        part rotor_top_washer_41 : Housing;
        part electric_motor_enclosure_with_stator_42 : Housing ;
        part motor_top_cap_43 : Housing;
        part motor_top_cap_screw_44 : Housing;
        part hex_nut_45 : Housing;
    }
}

package LinearActuatorModel2 {
    private import ISQ::*;
    private import SI::*;
    private import ScalarValues::*;

    port def SignalOut {
        out controlSignal;
    }

    port def SignalIn {
