    }

    port def TorqueIn {
        in outputTorque :> ISQ::torque;
    }

    port def SpinShaftDrive {
        out transferTorque :> ISQ::angularVelocity;
    }

    port def ShaftExtension {
        in transferTorque :> ISQ::length;
    }

    port def ScrewPort {
        in screwTorque :> ISQ ::torque;
        in clampingForce :> ISQ :: force;
    }

    port def InsertPort {
        in frictionForce :> ISQ :: force;
    }

    port def ScrewerPort {
        out screwTorque :> ISQ :: torque;
        out clampingForce :> ISQ :: force;
    }

    port def InserterPort {
        out frictionForce :> ISQ :: force;
    }

    port def ScrewGuidePort {
        out screwTorque :> ISQ :: torque;
    }

    port def ShaftGuidePort {
        in screwTorque :> ISQ :: torque;
        out shaftExtension :> ISQ :: length;
    }

    port def WasherPort {
        in clampingForce :> ISQ :: force;
        out distributeClampingForce :> ISQ :: force;
    }

    port def PinPort {
        in shearForce :> ISQ :: force;
        out fastenForce :> ISQ :: force;
    }

    port def PowerPort {
        in electricalPower :> ISQ :: power;
    }

    port def SpringPort {
        out springForce :> ISQ :: force;
    }

    port def NutPort {
        in screwTorque :> ISQ :: torque;
        out holdingForce :> ISQ :: force;
    }

    item def Signal;

    action def TurnOn {
        out controlSignal : Signal;
    }

    action def SendSignal {
        in electricalPower :> ISQ :: powerNumber;
        out signal : Signal;
    }

    action def FreeSpin {
        in outsideForce :> ISQ :: force;
        out spin :> ISQ :: angularVelocity;
    }

    action def ExtendingShaft {
        in driveTorque :> ISQ :: torque;
        out shaftExtension :> ISQ :: length;
    }

    part def ActuatorBase {
        attribute mass :> ISQ::mass;
        port screwPort : ScrewPort;
        port insertPort : InsertPort;
    }

    part def ShaftGuide {
        attribute mass :> ISQ::mass;
        port screwGuidePort : ScrewGuidePort;
    }

    part def ShaftWithMountingHole {
        attribute mass :> ISQ::mass;
        attribute length :> ISQ::length;
        port shaftGuidePort : ShaftGuidePort;
        perform action extendingShaft : ExtendingShaft;
        port insertPort : InsertPort;
    }

    part def MountingHoleGuard {
        attribute mass :> ISQ::mass;
        port inserterPort : InserterPort;
    }

    part def ShaftDriveORing {
        attribute mass :> ISQ::mass;
        port inserterPort : InserterPort;
    }

    part def ShaftStopper {
        attribute mass :> ISQ::mass;
        port inserterPort : InserterPort;
        port screwPort : ScrewPort;
    }

    part def ShaftStopperWasher {
        attribute mass :> ISQ::mass;
        port washerPort : WasherPort;
    }

    part def ShaftStopperScrew {
        attribute mass :> ISQ::mass;
        port screwerPort : ScrewerPort;
    }

    part def ShaftTopCap {
        attribute mass :> ISQ::mass;
        port inserterPort : InserterPort;
    }

    part def ShaftEnclosure {
        attribute mass :> ISQ::mass;
        port insertPort : InsertPort;
    }

    part def ShaftEnclosureCap {
        attribute mass :> ISQ::mass;
        port inserterPort : InserterPort;
        port screwPort : ScrewPort;
    }

    part def ShaftEnclosureCapScrew {
        attribute mass :> ISQ::mass;
        port screwerPort : ScrewerPort;
    }

    part def GearWheelLockingPin {
        attribute mass :> ISQ::mass;
        port pinPort : PinPort;
    }

    part def ShaftDriveBottomBallBearing {
        attribute mass :> ISQ::mass;
        port insertPort : InsertPort;
        port inserterPort : InserterPort;
        perform action freeSpin : FreeSpin;
    }

    part def ShaftDriveGearWheel {
        attribute mass :> ISQ::mass;
        attribute torque :> ISQ :: torque;
        port torqueIn : TorqueIn;
        port spinShaftDrive : SpinShaftDrive;
        perform action transferTorque;
    }

    part def ShaftDriveBallBearing {
        attribute mass :> ISQ::mass;
        port insertPort : InsertPort;
        port inserterPort : InserterPort;
        perform action freeSpin : FreeSpin;
    }

    part def ShaftDriveBumper {
        attribute mass :> ISQ::mass;
        port insertPort : InsertPort;
        port inserterPort : InserterPort;
    }

    part def ShaftDrive {
        attribute mass :> ISQ::mass;
        port torqueIn : TorqueIn;
        port shaftGuidePort : ShaftGuidePort;
    }

    part def RotorBottomSupportScrew {
        attribute mass :> ISQ::mass;
        port screwerPort : ScrewerPort;
    }

    part def BottomCapWithMountingHole {
        attribute mass :> ISQ::mass;
        port inserterPort : InserterPort;
    }

    part def BottomCapMountingPlate {
        attribute mass :> ISQ::mass;
        port insertPort : InsertPort;
        port screwPort : ScrewPort;
        port inserterPort : InserterPort;
    }

    part def MountingPlateScrew {
        attribute mass :> ISQ::mass;
        port screwerPort : ScrewerPort;
    }

    part def LimitSwitch {
        attribute mass :> ISQ::mass;
        port signalOut : SignalOut;
        perform action activateLimitSwitch;
    }

    part def LimitSwitchCarrier {
        attribute mass :> ISQ::mass;
    }

    part def Diode {
        attribute mass :> ISQ::mass;
        perform action switchCurrent;
        port signalIn : SignalIn;
    }

    part def Wire {
        attribute mass :> ISQ::mass;
        perform action carryCurrent;
    }

    part def ShaftEnclosureCentralScrew {
        attribute mass :> ISQ::mass;
        port screwerPort : ScrewerPort;
    }

    part def ShaftEnclosureSideScrew {
        attribute mass :> ISQ::mass;
        port screwerPort : ScrewerPort;
    }

    part def PowerCableWithMounting {
        attribute mass :> ISQ::mass;
        port powerPort : PowerPort;
        port screwPort : ScrewPort;
    }

    part def PowerCableScrew {
        attribute mass :> ISQ::mass;
        port screwerPort : ScrewerPort;
    }

    part def MotorCaseGasket {
        attribute mass :> ISQ::mass;
        port inserterPort : InserterPort;
    }

    part def BrushHolderPCB {
