        port screwPort : ScrewPort;
        port signalOut : SignalOut;
        perform action turnOn;
        perform action limitSwitchActivated;
        perform action sendSignal : SendSignal;
        state controlState {
            state off;
            state on {
                entry turnOn;
                do sendSignal;
                exit limitSwitchActivated;
            }
        }
    }

    part def BrushHolderPCBScrews {
        attribute mass :> ISQ::mass;
        port screwerPort : ScrewerPort;
    }   

    part def BrushSpring {
        attribute mass :> ISQ::mass;
        port springPort : SpringPort;
    }

    part def ElectricMotorBrush {
        attribute mass :> ISQ::mass;
        port powerPort : PowerPort;
        perform action spinRotor;
    }

    part def BrushWireScrew {
        attribute mass :> ISQ::mass;
        port screwerPort : ScrewerPort;
    }

    part def RotorBottomBearing {
        attribute mass :> ISQ::mass;
        port insertPort : InsertPort;
        port inserterPort : InserterPort;
        perform action freeSpin : FreeSpin;
    }

    part def LockingWasher {
        attribute mass :> ISQ::mass;
        port washerPort : WasherPort;
    }

    part def ElectricMotorRotor {
        attribute mass :> ISQ::mass;
        attribute electricalPower :> ISQ::power;
        port signalIn : SignalIn;
        port torqueOut : TorqueOut;
        perform action generateTorque;
    }

    part def RotorTopBearing {
        attribute mass :> ISQ::mass;
        port insertPort : InsertPort;
        port inserterPort : InserterPort;
        perform action freeSpin : FreeSpin;
    }

    part def RotorTopWasher {
        attribute mass :> ISQ::mass;
        port washerPort : WasherPort;
    }

    part def ElectricMotorEnclosureWithStator {
        attribute mass :> ISQ::mass;
        port insertPort : InsertPort;
        port inserterPort : InserterPort;
    }

    part def MotorTopCap {
        attribute mass :> ISQ::mass;
        port inserterPort : InserterPort;
        port screwPort : ScrewPort;
    }

    part def MotorTopCapScrew {
        attribute mass :> ISQ::mass;
        port screwerPort : ScrewerPort;
    }

    part def HexNut {
        attribute mass :> ISQ::mass;
        port screwPort : ScrewPort;
        port nutPort : NutPort;
    }

    part LinearActuator {
        part actuator_base_1 : ActuatorBase;
        part shaft_guide_2 : ShaftGuide ;
        part shaft_with_mounting_hole_3 : ShaftWithMountingHole;
        part mounting_hole_guard_4 : MountingHoleGuard;
        part shaft_drive_oring_5 : ShaftDriveORing;
        part shaft_stopper_6 : ShaftStopper ;
        part shaft_stopper_washer_7 : ShaftStopperWasher;
        part shaft_stopper_screw_8 : ShaftStopperScrew;
        part shaft_top_cap_9 : ShaftTopCap;
        part shaft_enclosure_10 : ShaftEnclosure ;
        part shaft_enclosure_cap_11 : ShaftEnclosureCap;
        part shaft_enclosure_cap_screw_12 : ShaftEnclosureCapScrew;
        part gear_wheel_locking_pin_13 : GearWheelLockingPin;
        part shaft_drive_bottom_ball_bearing_14 : ShaftDriveBottomBallBearing ;
        part shaft_drive_gear_wheel_15 : ShaftDriveGearWheel;
        part shaft_drive_ball_bearing_16 : ShaftDriveBallBearing;
        part shaft_drive_bumper_17 : ShaftDriveBumper;
        part shaft_drive_18 : ShaftDrive ;
        part rotor_bottom_support_screw_19 : RotorBottomSupportScrew;
        part bottom_cap_with_mounting_hole_20 : BottomCapWithMountingHole;
        part bottom_cap_mounting_plate_21 : BottomCapMountingPlate;
        part mounting_plate_screw_22 : MountingPlateScrew ;
        part limit_switch_23 : LimitSwitch;
        part limit_switch_carrier_24 : LimitSwitchCarrier;
        part diode_25 : Diode;
        part wire_26 : Wire ;
        part shaft_enclosure_central_screw_27 : ShaftEnclosureCentralScrew;
        part shaft_enclosure_side_screw_28 : ShaftEnclosureSideScrew;
        part power_cable_with_mounting_29 : PowerCableWithMounting;
        part power_cable_screw_30 : PowerCableScrew ;
        part motor_case_gasket_31 : MotorCaseGasket;
        part brush_holder_pcb_32 : BrushHolderPCB;
        part brush_holder_pcb_screws_33 : BrushHolderPCBScrews;
        part brush_spring_34 : BrushSpring ;
        part electric_motor_brush_35 : ElectricMotorBrush;
        part brush_wire_screw_36 : BrushWireScrew;
        part rotor_bottom_bearing_37 : RotorBottomBearing;
        part locking_washer_38 : LockingWasher ;
        part electric_motor_rotor_39 : ElectricMotorRotor;
        part rotor_top_bearing_40 : RotorTopBearing;
        part rotor_top_washer_41 : RotorTopWasher;
        part electric_motor_enclosure_with_stator_42 : ElectricMotorEnclosureWithStator ;
        part motor_top_cap_43 : MotorTopCap;
        part motor_top_cap_screw_44 : MotorTopCapScrew;
        part hex_nut_45 : HexNut;
    }
}

