package LinearActuatorActionDefinitions {
    public import ISQ::*;
    public import SI::*;
    public import ScalarValues::*;

    item def Power;
    item def TorqueCCW;
    item def TorqueCW;
    item def Signal;

    action def GivePower {
        out power : Power;
    }

    action def RotorSpinClockwise {
        in power : Power;
        out torquecw : TorqueCW;
    }

    action def RotorSpinCounterclockwise {
        in signal : Signal;
        out torqueccw : TorqueCCW;
    }

    action def GearSpinClockwise {
        in torqueccw : TorqueCCW;
        out torquecw : TorqueCW;
    }

    action def GearSpinCounterclockwise {
        in torquecw : TorqueCW;
        out torqueccw : TorqueCCW;
    }

    action def MoveForward {
        in torqueccw : TorqueCCW;
        out length = length +1;
    }

    action def MoveBackward {
        in torquecw : TorqueCW;
        out length = length -1;
    }

    action def ActivateFrontLimitSwitch {
        out signal : Signal;
    }

    action def ActivateBackLimitSwitch {
        out signal : Signal;
    }

    action def MoveMore {
        out length = length +1;
    }

    action def RotorStopSpin {
        in signal : Signal;
    }

    action def ReversePolarity {
        in signal : Signal;
        out reversesignal : Signal;
    }

    action def LinearlyActuateForward {
        action givepower : GivePower {
            out power;
        }
        action rotorspinclockwise : RotorSpinClockwise{
            in power;
            out torquecw;
        }
        action gearspincounterclockwise : GearSpinCounterclockwise{
            in torquecw;
            out torqueccw;
        }
        action moveforward : MoveForward{
            in torqueccw;
            out length;
        }
        action activatefrontlimitswitch : ActivateFrontLimitSwitch {
            out signal;
        }
        action reversepolarity : ReversePolarity {
            in signal;
            out reversesignal;
        }

        in power : Power;

        flow power to rotorspinclockwise.power;
        first givepower then rotorspinclockwise;

        flow rotorspinclockwise.torquecw to gearspincounterclockwise.torquecw;
        first rotorspinclockwise then gearspincounterclockwise;

        flow gearspincounterclockwise.torqueccw to moveforward.torqueccw;
        first gearspincounterclockwise then moveforward;
        then merge continue;
        then decide;
            if length <4 then moveforward;
            else activatefrontlimitswitch;
        then continue;
        flow activatefrontlimitswitch.signal to reversepolarity.signal;
        first activatefrontlimitswitch then reversepolarity;

        out reversesignal : Signal;
    }

    action def LinearlyActuateBackward {
        action reversepolarity : ReversePolarity {
            in signal;
            out reversesignal;
        }
        action rotorspincounterclockwise : RotorSpinCounterclockwise{
            in signal;
            out torqueccw;
        }
        action gearspinclockwise : GearSpinClockwise{
            in torqueccw;
            out torquecw;
        }
        action movebackward : MoveBackward{
            in torquecw;
            out length;
        }
        action activatebacklimitswitch : ActivateBackLimitSwitch {
            out signal;
        }
        action rotorstopspin : RotorStopSpin {
            in signal;
        }
        in reversesignal : Signal;
        flow reversesignal to rotorspincounterclockwise.signal;
        first reversepolarity then rotorspincounterclockwise;

        flow rotorspincounterclockwise.torqueccw to gearspinclockwise.torqueccw;
        first rotorspincounterclockwise then gearspinclockwise;

        flow gearspinclockwise.torquecw to movebackward.torquecw;
        first gearspinclockwise then movebackward;
        then merge continue2;
        then decide;
            if length >0 then movebackward;
            else activatebacklimitswitch;
        then continue2;
        flow activatebacklimitswitch.signal to rotorstopspin.signal;
        first activatebacklimitswitch then rotorstopspin;
    }

    action def LinearlyActuate {
        action linearlyactuateforward : LinearlyActuateForward {
            in power : Power;
            out reversesignal : Signal;
        }
        action linearlyactuatebackward : LinearlyActuateBackward {
            in reversesignal : Signal;
        }
        in power : Power;
        flow power to linearlyactuateforward.power;
        first linearlyactuateforward then linearlyactuatebackward;
        flow linearlyactuateforward.reversesignal to linearlyactuatebackward.reversesignal;
    }
}

package LinearActuatorModel8 {
    public import LinearActuatorPartDefinitions::*;
    public import ISQ::*;
    public import SI::*;
    public import ScalarValues::*;

    item def Power;
    item def TorqueCCW;
    item def TorqueCW;
    item def Signal;

    action def GivePower {
        out power : Power;
    }

    action def RotorSpinClockwise {
        in power : Power;
        out torquecw : TorqueCW;
    }

    action def RotorSpinCounterclockwise {
        in power : Power;
        out torqueccw : TorqueCCW;
    }

    action def GearSpinClockwise {
        in torqueccw : TorqueCCW;
        out torquecw : TorqueCW;
    }

    action def GearSpinCounterclockwise {
        in torquecw : TorqueCW;
        out torqueccw : TorqueCCW;
    }

    action def MoveForward {
        in torqueccw : TorqueCCW;
        out length = length +1;
    }

    action def MoveBackward {
        in torquecw : TorqueCW;
        out length = length -1;
    }

    action def ActivateFrontLimitSwitch {
        out signal : Signal;
    }

    action def ActivateBackLimitSwitch {
        out signal : Signal;
    }

    action def MoveMore {
        out length = length +1;
    }

    action def RotorStopSpin {
        in signal : Signal;
    }

    action def LinearlyActuate {
        action givepower : GivePower {
            out power;
        }
        action rotorspinclockwise : RotorSpinClockwise{
            in power;
            out torquecw;
        }
        action rotorspincounterclockwise : RotorSpinCounterclockwise{
            in signal;
            out torqueccw;
        }
        action gearspinclockwise : GearSpinClockwise{
            in torqueccw;
            out torquecw;
        }
        action gearspincounterclockwise : GearSpinCounterclockwise{
            in torquecw;
            out torqueccw;
        }
        action moveforward : MoveForward{
            in torqueccw;
            out length;
        }
        action movebackward : MoveBackward{
            in torquecw;
            out length;
        }
        action activatefrontlimitswitch : ActivateFrontLimitSwitch {
            out signal;
        }
        action activatebacklimitswitch : ActivateBackLimitSwitch {
            out signal;
        }
        action movemore : MoveMore {
            out length;
        }
        action rotorstopspin : RotorStopSpin {
            in signal;
        }

        in power : Power;

        flow givepower.power to rotorspinclockwise.power;
        first givepower then rotorspinclockwise;

        flow rotorspinclockwise.torquecw to gearspincounterclockwise.torquecw;
        first rotorspinclockwise then gearspincounterclockwise;

        flow gearspincounterclockwise.torqueccw to moveforward.torqueccw;
        first gearspincounterclockwise then moveforward;
        first moveforward then movemore;
        then merge continue;
        then decide;
            if length <4 then movemore;
            else activatefrontlimitswitch;
        then continue;
        flow activatefrontlimitswitch.signal to rotorspincounterclockwise.signal;
        first activatefrontlimitswitch then rotorspincounterclockwise;

        flow rotorspincounterclockwise.torqueccw to gearspinclockwise.torqueccw;
        first rotorspincounterclockwise then gearspinclockwise;

        flow gearspinclockwise.torquecw to movebackward.torquecw;
        first gearspinclockwise then movebackward;
        then merge continue2;
        then decide;
            if length >0 then movebackward;
            else activatebacklimitswitch;
        then continue2;
        flow activatebacklimitswitch.signal to rotorstopspin.signal;
        first activatebacklimitswitch then rotorstopspin;
    }

    part def LinearActuatorAssembly {
        attribute mass :> ISQ::mass;

        item power : Power;
        item torqueccw : TorqueCCW;
        item torquecw : TorqueCW;
        item signal : Signal;

        part actuatorbase[1] : ActuatorBase;
        part shaftenclosurecentralscrew[1] : ShaftEnclosureCentralScrew;
        part limitswitchcarrier[1] : LimitSwitchCarrier;
        part limitswitch[2] : LimitSwitch {
            perform action activatefrontlimitswitch : ActivateFrontLimitSwitch;
            perform action activatebacklimitswitch : ActivateBackLimitSwitch;
        }
        part diode[2] : Diode;
        part wire[1] : Wire;
        part mountingplatescrew[4] : MountingPlateScrew;
        part bottomcapmountingplate[1] : BottomCapMountingPlate;
        part bottomcapwithmountinghole[1] : BottomCapWithMountingHole;
