    part def Thing {
        attribute mass :> ISQ :: mass;
    }

    part person : Person {
        event occurrence plugInPowerSent;
    }
    part twelvevoltbattery : TwelveVoltBattery {
        event occurrence plugInPowerReceived;
        event occurrence sendPowerSent;
    }
        part electricmotorrotorr : ElectricMotorRotor {
            event occurrence sendPowerReceived;
            event occurrence sendTorqueSent;
        }
        part shaftdrivegearwheell : ShaftDriveGearWheel {
            event occurrence sendTorqueReceived;
            event occurrence sendLinearMovementSent;
        }
        part shaftwithmountingholee : ShaftWithMountingHole {
            event occurrence sendLinearMovementReceived;
        }
    occurrence def plugInPower;
    occurrence def sendPower;
    occurrence def sendTorque;
    occurrence def sendLinearMovement;

    occurrence def LinearActuatorInteraction {
        ref part :>> person;
        ref part :>> twelvevoltbattery;
        ref part :>> electricmotorrotorr;
        ref part :>> shaftdrivegearwheell;
        ref part :>> shaftwithmountingholee;

        message plugInPowerMessage of plugInPower
            from person.plugInPowerSent
            to twelvevoltbattery.plugInPowerReceived;
        message sendPowerMessage of sendPower
            from twelvevoltbattery.sendPowerSent
            to electricmotorrotorr.sendPowerReceived;
        message sendTorqueMessage of sendTorque
            from electricmotorrotorr.sendTorqueSent
            to shaftdrivegearwheell.sendTorqueReceived;
        message sendLinearMovementMessage of sendLinearMovement
            from shaftdrivegearwheell.sendLinearMovementSent
            to shaftwithmountingholee.sendLinearMovementReceived;

        first plugInPowerMessage then sendPowerMessage then sendTorqueMessage then sendLinearMovementMessage;
    }
}

package LinearActuatorStateDefinitions {
    public import LinearActuatorActionDefinitions::*;

    item def PowerFromBattery;
    item def FrontLimitSwitchSignal;
    item def BackLimitSwitchSignal;

    state def LinearActuatorState {
        entry; then off;

        state off;

        transition OffToActuatingForward
            first off
            accept PowerFromBattery
            then ShaftActuatesForward;

        state ShaftActuatesForward {
            entry action rotorspinclockwise : RotorSpinClockwise;
            do action linearlyactuateforward : LinearlyActuateForward;
            exit action activatefrontlimitswitch : ActivateFrontLimitSwitch;
        }

        transition ShaftActuatesForwardToShaftActuatesBackward
            first ShaftActuatesForward
            accept FrontLimitSwitchSignal
            then ShaftActuatesBackward;

        state ShaftActuatesBackward {
            entry action reversepolarity : ReversePolarity;
            do action linearlyactuatebackward : LinearlyActuateBackward;
            exit action activatebacklimitswitch : ActivateBackLimitSwitch;
        }

        transition ShaftActuatesBackwardToOff
            first ShaftActuatesBackward
            accept BackLimitSwitchSignal
            then off;
    }
}

package LinearActuatorModel9 {
    public import LinearActuatorPartDefinitions::*;
    public import ISQ::*;
    public import SI::*;
    public import ScalarValues::*;

    item def PowerFromBattery;
    item def FrontLimitSwitchSignal;
    item def BackLimitSwitchSignal;

    state def LinearActuatorState {
        entry; then off;

        state off;

        transition OffToActuatingForward
            first off
            accept PowerFromBattery
            then ShaftActuatesForward;

        state ShaftActuatesForward;

        transition ShaftActuatesForwardToShaftActuatesBackward
            first ShaftActuatesForward
            accept FrontLimitSwitchSignal
            then ShaftActuatesBackward;

        state ShaftActuatesBackward;

        transition ShaftActuatesBackwardToOff
            first ShaftActuatesBackward
            accept BackLimitSwitchSignal
            then off;
    }
}

package LinearActuatorModel10 {
    public import LinearActuatorDefinitions::*;
    public import LinearActuatorModel4::*;

    part def Person {
        attribute mass :> ISQ :: mass;
    }
    part def Thing {
        attribute mass :> ISQ :: mass;
    }

    use case def 'Linearly Push Item' {
        subject linearactuator : LinearActuator;
        actor person : Person;
        actor thing : Thing;
        objective {
            doc /* Push an object using the linear actuator*/
        }
    }

    use case def 'Supply Power to Linear Actuator' {
        subject linearactuator : LinearActuator;
        actor person : Person;
        actor twelvevoltbattery : TwelveVoltBattery;
        objective {
            doc /* Supply power to the linear actuator*/
        }
    }

    use case def 'Shaft Actuates Forward and Pushes Thing' {
        subject linearactuator : LinearActuator;
        actor thing : Thing;
        objective {
            doc /* Actuate the shaft and push the thing*/
        }
    }

    use case 'linearly push item' : 'Linearly Push Item' {
        subject linearactuator;
        actor person : Person;
        actor thing : Thing;
        first start;
        then use case 'supply power to linear actuator' : 'Supply Power to Linear Actuator' {
            subject linearactuator;
            actor :>> person = 'linearly push item' :: person;
            actor twelvevoltbattery;
        }
        then use case 'shaft actuates forward and pushes thing' : 'Shaft Actuates Forward and Pushes Thing' {
            subject linearactuator;
            actor :>> thing = 'linearly push item' :: thing;
        }
        then done;
    }
}

