package LinearActuatorahhh {
    part def Driver;
    part def Vehicle;
    part def Speedometer;
    part def Engine;
    part def CruiseController;

    part driver : Driver {
        event occurrence setSpeedSent;
    }
        part cruisecontroller : CruiseController {
            event occurrence setSpeedReceived;
            event occurrence sensedSpeedReceived;
            event occurrence fuelCommandSent;
        }
        part speedometer : Speedometer {
            event occurrence sensedSpeedSent;
        }
        part engine : Engine {
            event occurrence fuelCommandReceived;
        }

    occurrence def SetSpeed;
    occurrence def SensedSpeed;
    occurrence def FuelCommand;

    occurrence def CruiseControlInteraction {
        ref part :>> driver;
        ref part cruisecontroller :>> cruisecontroller;
        ref part speedometer :>> speedometer;
        ref part engine :>> engine;

        message setSpeedMessage of SetSpeed
            from driver.setSpeedSent
            to cruisecontroller.setSpeedReceived;

        message sensedSpeedMessage of SensedSpeed
            from speedometer.sensedSpeedSent
            to cruisecontroller.sensedSpeedReceived;

        message fuelCommandMessage of FuelCommand
            from cruisecontroller.fuelCommandSent
            to engine.fuelCommandReceived;

        first setSpeedMessage then sensedSpeedMessage; 

    }

    occurrence def CruiseControlInteraction2 {
        ref part driver : Driver {
            event setSpeedMessage.sourceEvent;
        }
            part cruisecontroller : CruiseController {
                event setSpeedMessage.targetEvent;
                event sensedSpeedMessage.targetEvent;
                event fuelCommandMessage.sourceEvent;
            }
            part speedometer : Speedometer {
                event sensedSpeedMessage.sourceEvent;
            }
            part engine : Engine {
                event fuelCommandMessage.targetEvent;
            }
        message setSpeedMessage of SetSpeed;
        then message sensedSpeedMessage of SensedSpeed;
        message fuelCommandMessage of FuelCommand;
    }
}
